INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist jedes Projekt nach DIN 69901 risikobehaftet?', 2, '[{"text": "Ja", "correct": true, "because": "Risiken sind ein Merkmal von Projekten"}, {"text": "Nein", "correct": false, "because": "Risiken sind nicht zwingend"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Merkmal macht ein Projekt risikobehaftet?', 3, '[{"text": "Einmaligkeit", "correct": true, "because": "Neue Aufgaben bergen Unsicherheiten"}, {"text": "Feste Struktur", "correct": false, "because": "Struktur reduziert Risiken"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind Projekte ohne Risiken möglich?', 2, '[{"text": "Nein", "correct": true, "because": "Unvorhersehbare Ereignisse gibt es immer"}, {"text": "Ja", "correct": false, "because": "Risiken sind unvermeidbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Faktor erhöht das Risiko in einem IT-Projekt?', 3, '[{"text": "Neue Technologie", "correct": true, "because": "Ungetestete Systeme sind unsicher"}, {"text": "Bekannte Software", "correct": false, "because": "Vertrautheit senkt Risiken"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann ein Projekt ohne Risikoanalyse erfolgreich sein?', 2, '[{"text": "Nein", "correct": true, "because": "Risiken müssen identifiziert werden"}, {"text": "Ja", "correct": false, "because": "Zufallserfolg ist möglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Risiken entstehen durch Komplexität. b) Risiken sind immer vermeidbar.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Komplexität erzeugt Risiken, Vermeidung ist nicht immer möglich"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Maßnahme hilft, Risiken zu minimieren?', 3, '[{"text": "Risikoanalyse", "correct": true, "because": "Identifikation ermöglicht Steuerung"}, {"text": "Ignorieren", "correct": false, "because": "Erhöht die Gefahr"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist die Risikobehaftung eines Projekts planbar?', 2, '[{"text": "Ja", "correct": true, "because": "Risiken können antizipiert werden"}, {"text": "Nein", "correct": false, "because": "Unvorhersehbares bleibt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Element gehört zur Risikobewertung?', 4, '[{"text": "Wahrscheinlichkeit", "correct": true, "because": "Misst das Risiko"}, {"text": "Projektname", "correct": false, "because": "Irrelevant für Bewertung"}]'),
('00000000-0000-0000-0000-000000000000', 'Können Risiken in einem Projekt komplett ausgeschlossen werden?', 2, '[{"text": "Nein", "correct": true, "because": "Unvorhersehbare Faktoren bleiben"}, {"text": "Ja", "correct": false, "because": "Unrealistisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Projektphase ist besonders risikobehaftet?', 3, '[{"text": "Initiierung", "correct": true, "because": "Viele Unbekannte zu Beginn"}, {"text": "Abschluss", "correct": false, "because": "Risiken meist geklärt"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind technische Risiken die einzigen in IT-Projekten?', 2, '[{"text": "Nein", "correct": true, "because": "Auch organisatorische Risiken zählen"}, {"text": "Ja", "correct": false, "because": "Risiken sind vielfältig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Risiken sind typisch für Softwareprojekte?', 4, '[{"text": "Technische Fehler", "correct": true, "because": "Häufig bei Entwicklung"}, {"text": "Zeitüberschreitung", "correct": true, "because": "Planung oft schwierig"}, {"text": "Teamgröße", "correct": false, "because": "Kein Risiko an sich"}]'),
('00000000-0000-0000-0000-000000000000', 'Muss ein Projektmanager alle Risiken kennen?', 2, '[{"text": "Nein", "correct": true, "because": "Unvorhersehbares bleibt unkenntlich"}, {"text": "Ja", "correct": false, "because": "Unrealistische Erwartung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Methode hilft bei der Risikoidentifikation?', 3, '[{"text": "Brainstorming", "correct": true, "because": "Fördert Ideen zur Risikosuche"}, {"text": "Warten", "correct": false, "because": "Passivität erhöht Gefahr"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind Risiken immer negativ?', 2, '[{"text": "Nein", "correct": true, "because": "Chancen sind positive Risiken"}, {"text": "Ja", "correct": false, "because": "Risiken können auch Chancen sein"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Ansatz reduziert Risiken in Projekten?', 3, '[{"text": "Prototyping", "correct": true, "because": "Testet früh Unsicherheiten"}, {"text": "Keine Tests", "correct": false, "because": "Erhöht Fehlerquote"}]'),
('00000000-0000-0000-0000-000000000000', 'Können Risiken durch Teamarbeit steigen?', 2, '[{"text": "Ja", "correct": true, "because": "Kommunikationsprobleme sind möglich"}, {"text": "Nein", "correct": false, "because": "Teamarbeit kann Risiken senken"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren machen ein Projekt risikobehaftet?', 4, '[{"text": "Innovative Ansätze", "correct": true, "because": "Unbekanntes birgt Risiken"}, {"text": "Komplexität", "correct": true, "because": "Erhöht Fehlerquellen"}, {"text": "Routineaufgaben", "correct": false, "because": "Weniger unsicher"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist die Risikobehaftung messbar?', 3, '[{"text": "Ja", "correct": true, "because": "Mit Wahrscheinlichkeit und Auswirkung"}, {"text": "Nein", "correct": false, "because": "Messbarkeit ist möglich"}]');